public int CountSetBitsBrute(int n)
{
    int total = 0;
    for (int i = 1; i <= n; i++)
    {
        int x = i;
        while (x > 0)
        {
            total += x & 1;
            x >>= 1;
        }
    }
    return total;
}

public int CountSetBitsOptimized(int n)
{
    if (n <= 0) return 0;
    int x = LargestPowerOf2(n);
    int bitsUpTo2x = x * (1 << (x - 1));
    int remaining = n - (1 << x) + 1;
    int rest = n - (1 << x);
    return bitsUpTo2x + remaining + CountSetBitsOptimized(rest);
}

private int LargestPowerOf2(int n)
{
    int x = 0;
    while ((1 << x) <= n)
        x++;
    return x - 1;
}
